#!/bin/bash

# Evaluation sweep over the TRAINED connector checkpoints (the `txf` configs generated by
# tools/preprocess/create_yamls_models_lalm_txf.py), on both evaluation domains.
#
# HOW THIS DIFFERS FROM eval_lalm_decoder.sh. That script sweeps the *untrained* model configs
# (stock encoder + stock decoder + randomly-initialised connector) across every dataset, which
# is a full model x dataset cross product. This one evaluates each trained checkpoint on the
# language it was TRAINED on, because the checkpoints are language-specific: a connector
# trained on Urdu has no claim on Hausa, and running the full 82 x 22 cross product would be
# ~1800 evaluations, almost all of them meaningless.
#
# So the sweep is a matched pairing, and it is written explicitly rather than looped, because
# the language a checkpoint was trained on is baked into its config name and the eval sets it
# should be paired with are not derivable from that name alone:
#
#   training config    ->  held-out domain (FLEURS)     +  in-domain (WorldSpeech)
#   en_us              ->  fleurs_en_us_test            +  worldspeech_en_us_test
#   fr_ca              ->  fleurs_fr_fr_test            +  worldspeech_fr_ca_test
#   es_mx              ->  fleurs_es_419_test           +  worldspeech_es_mx_test
#   ...
#
# Note fr_ca -> fleurs_fr_fr and es_mx -> fleurs_es_419: the training variety and the FLEURS
# evaluation variety are not the same string, which is exactly the accent axis the analysis
# tracks. Getting this pairing wrong would silently evaluate the wrong cell.
#
# BOTH CHECKPOINTS PER CELL. Every cell has a best-step and a step-1000 checkpoint, and both
# are swept: the study reports best-checkpoint CER as primary and final as secondary, and the
# gap between them is itself the overfitting metric. Evaluating only one answers a different
# question.
#
# Serial 11 pairs with serial 10, which carries the eval-only baselines (whisper-medium,
# Voxtral-Mini, Qwen2-Audio evaluated directly, no connector trained). 10 and 11 use the SAME
# FLEURS test configs, so `serial 11 minus serial 10` is the like-for-like measure of what
# connector training actually bought. That pairing is the point of the serial choice -- these
# are project serials for the LALM study, not QuantizedASR's short-ml 3xx/4xx blocks.
#
# NOT COVERED: am_et and crs_sc have finished W&B runs but no uploaded checkpoints yet, and
# es_es was superseded by es_mx (its checkpoints have no step-1000). Add them here once
# create_yamls_models_lalm_txf.py reports them.

# (training config stem | FLEURS eval | in-training WorldSpeech evals | held-out WorldSpeech evals)
#
# WorldSpeech ships several country variants per language, and the study only trained on some of
# them. Evaluating the rest is pure inference cost and turns one in-domain number into a
# dialect/accent generalisation axis:
#
#   in-training   the variety (or varieties) this cell trained on. In-distribution.
#   held-out      never in the training mix -- zero-shot accent transfer. English has 7 of
#                 these, Spanish 8, French 2. This is the accent-robustness axis
#                 docs/EVAL_DATASET_PLAN.md wanted EdAcc for, available here in-domain.
#
# `ta_lk` is in the HELD-OUT column despite being named in Tamil's training config: the strict
# `< 30 s` cap removed all 23,261 of its clips, so the model never saw it. That makes it the
# most informative single eval here -- held-out dialect transfer for a variety the config
# claims to have trained on.
#
# --eval_set controls the cost:
#   primary   FLEURS + in-training WorldSpeech only          (the default; ~1 eval set/language)
#   all       adds every held-out variant                    (the accent axis; ~3x the runs)

# The array itself is GENERATED by tools/preprocess/create_yamls_worldspeech_lalm.py, from the
# same table that writes the dataset YAMLs. It used to live inline here and be maintained by
# hand, which meant the pairing and the configs could disagree without anything noticing. Now a
# language is added in exactly one place.
PAIRINGS_FILE="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)/tools/preprocess/worldspeech_lalm_pairings.sh"
if [ ! -f "$PAIRINGS_FILE" ]; then
    echo "ERROR: $PAIRINGS_FILE is missing." >&2
    echo "Run: python tools/preprocess/create_yamls_worldspeech_lalm.py" >&2
    exit 1
fi
# shellcheck source=/dev/null
source "$PAIRINGS_FILE"

# ha_ng's in-training column now includes both varieties. The training runs already evaluate
# ha_ng on disco-eth/WorldSpeech test, so that one cell is a duplicate -- kept for symmetry
# because the sweep is per-checkpoint and the training-time eval was per-training-run.

VARIANTS=(
    "earth"
    "fire"
    "global"
    "water"
    # base exists for ta_in only -- handled by the existence check in the loop.
    "base"
)

models=''
eval_set='primary'

VALID_ARGS=$(getopt -o '' --long models:,eval_set: -- "$@")
if [[ $? -ne 0 ]]; then
    exit 1;
fi

eval set -- "$VALID_ARGS"
while [ : ]; do
  case "$1" in
    --models)
        models=${2}
        shift 2
        ;;
    --eval_set)
        eval_set=${2}
        shift 2
        ;;
    --) shift;
        break
        ;;
  esac
done

if [ -n "$models" ]; then
    read -ra VARIANTS <<< "$models"
fi

base_cmd="python -m tools.evaluate --serial 11 --batch_size 128"

for pairing in "${PAIRINGS[@]}"; do
    IFS='|' read -r lang fleurs_cfg ws_in ws_held <<< "$pairing"

    # Build this language's eval list according to --eval_set.
    eval_cfgs="$fleurs_cfg $ws_in"
    if [ "$eval_set" = "all" ]; then
        eval_cfgs="$eval_cfgs $ws_held"
    fi

    for variant in "${VARIANTS[@]}"; do
        # Both checkpoints per cell: the best step (whatever it was) and step 1000. The best
        # step differs per cell, so the config is found by glob rather than assumed.
        for model_cfg_path in configs/models/cq2a_whisper_medium_tiny_aya_${variant}_txf_ws_${lang}_*.yaml; do
            [ -e "$model_cfg_path" ] || continue
            model_cfg=$(basename "$model_cfg_path")

            for dataset_cfg in $eval_cfgs; do
                [ -n "$dataset_cfg" ] || continue
                cmd="$base_cmd --config configs/models/$model_cfg configs/datasets/$dataset_cfg"
                echo "$cmd"
                $cmd
            done
        done
    done
done
